const book='<a class="link" href="/assets/ktu-2024-handbook.pdf" target="_blank" rel="noopener">Open 2024 handbook ↗</a>',ruleRef=x=>handbookIndex[x[0]]?.[0]||x[0],filterRule=title=>rules.filter(x=>x[1].toLowerCase().includes(title.toLowerCase()));function commonGuidance(){return `<details class="rulesummary"><summary>General rules that apply to every activity</summary><p>Only activities completed during the programme qualify. Use the highest achievement level for the same event; do not add participation and winning points together. Verify the evidence, segment maximum and earlier awards.</p><p>Regular B.Tech: 120 total, 40 per group. Lateral entry: 90 total, 30 per group. PwD: 60 total, 20 per group. Keep the semester activity file and submit the evidence to the SFA for verification.</p><small>2024 handbook · printed pp. 2, 17–18. The published handbook and separately notified course approvals govern.</small></details>`}
function handbookSource(x){return `2024 handbook · Table 2 · printed p. ${handbookIndex[x[0]][1]-3} (PDF p. ${handbookIndex[x[0]][1]})`}
function ruleText(x){let v=awardCatalog[x[0]];return `<div class="rulesummary"><span class="label">Rule ${ruleRef(x)} · Group ${gr[x[2]]}</span><h3>${E(x[1])}</h3><p>${E(x[4])}</p><b>Documentary evidence</b><p>${E(x[5])}</p><strong>${x[0]==='3.17'?'1 point per approved hour':x[3]+' points for this outcome'}</strong><p>Limit: ${v[2]} points · ${E(v[3])}.</p><small>${handbookSource(x)}</small></div>`}
function assist(){return `<section class="aid"><div class="between"><span class="kicker">Activity point finder</span>${book}</div><p>All 63 activity entries · 157 selectable outcomes. Search by number, activity, level or award. This reference does not fill in your submission.</p>${rulePicker('ruleSelect')}<div id="suggestion" aria-live="polite"></div>${commonGuidance()}</section>`}function suggest(){let x=rules.find(x=>x[0]===$('#ruleSelect').value);$('#suggestion').innerHTML=x?ruleText(x):''}
function reviewAid(r){let x=rules.find(x=>x[0]===r.ruleRef),xs=x?[x]:filterRule(r.title);let duplicate=recs(r.student).some(a=>a.id!==r.id&&a.title.trim().toLowerCase()===r.title.trim().toLowerCase()&&a.date===r.date);return `<section class="sheet data"><div class="between"><h3>Verification guide</h3>${book}</div>${xs.length===1?ruleText(xs[0])+`<p><b>${xs[0][2]===r.grp&&xs[0][3]===r.points?'Claim matches the example group and value.':'Check discrepancy: claimed group or points differ from the handbook example.'}</b> Verify eligibility and evidence before approving.</p>`:`<p>${xs.length?'Multiple possible score bands. Check the original scorecard.':'No exact example rule identified.'} Consult the full handbook to confirm the group, evidence and award.</p>`}${duplicate?'<p class="warn">Possible duplicate: the same student has another entry with this title and date.</p>':''}${!r.filename?'<small>No certificate attached to this sample record.</small>':''}</section>`}
let shelf={notes:'',pins:[]};function shelfKey(){return 'cl-shelf-'+S.me.role+'-'+S.me.id}async function loadShelf(){if(isDemo){try{shelf=JSON.parse(localStorage.getItem(shelfKey()))||{notes:'',pins:[]}}catch{}}else shelf=await api('workspace');}async function saveShelf(v){try{if(isDemo)localStorage.setItem(shelfKey(),JSON.stringify(v));else await api('workspace',v);shelf=v;return true}catch{toast('Could not save this change. Please try again.');return false}}
function workspacePage(){return heading('Personal workspace','My workspace',teach()?'Search class records, pin cases for follow-up and keep your own notes.':'Your submitted activities in one place, with saved records and personal notes.')+`<div class="shelfgrid"><section class="sheet"><div class="between"><h3>Record library</h3><button class="btn" onclick="exportLibrary()">${I('download')} CSV</button></div><div class="toolbar"><div class="field">${I('search')}<input aria-label="Search library" placeholder="Search activity or student…" id="wq" oninput="drawLibrary()"></div><select id="wf" class="entry" aria-label="Filter records" onchange="drawLibrary()"><option>All records</option><option>Pinned</option><option>Pending</option><option>Approved</option><option>Correction requested</option></select></div><div id="library"></div></section><section class="sheet notepad"><span class="kicker">Personal notebook</span><h3>Follow-up notes</h3><p>Only shown in your workspace${isDemo?' in this browser':''}.</p><textarea id="notetxt" class="entry" maxlength="6000" rows="7" placeholder="Add reminders or questions for your next review…">${E(shelf.notes)}</textarea><button class="primary" onclick="saveNote()">Save notes</button></section></div>`}async function saveNote(){if(await saveShelf({...shelf,notes:$('#notetxt').value}))toast('Notes saved')}function libraryData(){let q=$('#wq').value.toLowerCase(),f=$('#wf').value;return S.records.filter(r=>(r.title+' '+(stud(r.student)?.name||'')).toLowerCase().includes(q)&&(f==='All records'||f==='Pinned'&&shelf.pins.includes(r.id)||r.status===f))}function drawLibrary(){let rs=libraryData();$('#library').innerHTML=rs.map(r=>`<div class="librow">${row(r)}<button class="pin ${shelf.pins.includes(r.id)?'on':''}" aria-label="${shelf.pins.includes(r.id)?'Unpin':'Pin'} ${E(r.title)}" aria-pressed="${shelf.pins.includes(r.id)}" onclick="pinRecord(${r.id})">${I('bookmark')}</button></div>`).join('')||'<p class="empty">No records match this filter.</p>';paint()}async function pinRecord(id){if(await saveShelf({...shelf,pins:shelf.pins.includes(id)?shelf.pins.filter(n=>n!==id):[...shelf.pins,id]}))drawLibrary()}function exportLibrary(){let rows=[['Student','Register','Activity','Date','Group','Points','Status'],...libraryData().map(r=>[stud(r.student).name,stud(r.student).reg,r.title,r.date,gr[r.grp],r.points,r.status])];let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(v=>v.map(k=>'"'+String(k).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv'}));a.download='campusledger-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

