function calcAward(records,student,key,hours){let rule=awardCatalog[key];if(!rule)return null;let [group,rate,cap,head]=rule;if(key==='3.17'){if(!Number.isSafeInteger(Number(hours))||Number(hours)<1)return null;rate=Number(hours)}let previous=records.filter(v=>v.student===student&&v.status==='Approved'),credited=previous.filter(v=>awardCatalog[v.ruleRef]?.[3]===head).reduce((n,v)=>n+v.points,0),groupTotal=previous.filter(v=>v.grp===group).reduce((n,v)=>n+v.points,0);return {group,rate,cap,head,credited,groupTotal,available:Math.min(rate,Math.max(0,cap-credited),Math.max(0,40-groupTotal))}}
function lookupPanel(r){return `<form class="sheet lookup" id="review"><div class="between"><span class="kicker">Teacher tools · 2024 scheme</span>${book}</div><h2>Handbook rule lookup</h2><p>Search all 63 handbook entries. Select the level, result or score band supported by the submitted evidence.</p><div class="subject">${ava(stud(r.student).name)}<div><b>${E(stud(r.student).name)}</b><small>${E(r.title)} · Requested ${r.points} pts</small></div></div><label class="lab" for="teacherRuleSearch">Handbook activity and qualifying detail</label>${rulePicker('teacherRule',r.ruleRef)}<div id="hourFields" hidden><label class="lab" for="verifiedHours">Verified completed course hours</label><input class="entry" id="verifiedHours" type="number" min="1" step="1" placeholder="Enter documented whole hours" oninput="refreshAward()"><small>Check the current university-approved course list. Never round or infer an undocumented duration.</small></div><div id="calculation" aria-live="polite"></div>${commonGuidance()}<label class="lab" for="note">Feedback to student (optional for approval)</label><textarea class="entry" id="note" rows="2" placeholder="Add a short decision note…"></textarea><div class="action"><button id="accept" class="primary" value="Approved" disabled>Approve award</button><button class="btn" value="Correction requested">Request clarification</button></div></form>`}
function refreshAward(){let r=S.records.find(x=>x.id===Number($('#review').dataset.record)),key=$('#teacherRule').value,calc=calcAward(S.records,r.student,key,$('#verifiedHours')?.value),x=rules.find(x=>x[0]===key);$('#hourFields').hidden=key!=='3.17';if(key!=='3.17')$('#verifiedHours').value='';$('#accept').disabled=true;$('#accept').textContent=calc?'Approve '+calc.available+' points':'Approve award';$('#calculation').innerHTML=key==='3.17'&&!calc?ruleText(x)+'<p>Enter verified hours to calculate an award.</p>':!calc?'<div class="rulesummary"><b>Points not determined</b><p>No supported rule and qualifying detail selected. Consult the handbook or request clarification. No points will be awarded automatically.</p></div>':`<div class="awardcard"><span class="label">Rule ${ruleRef(x)} · Group ${gr[calc.group]}</span><h3>${x[1]}</h3><p>${E(x[4])}</p><p><b>Evidence:</b> ${E(x[5])}</p><small>${handbookSource(x)}</small><div class="awardstats"><div><small>Handbook rate</small><b>${calc.rate} pts</b></div><div><small>Already approved¹</small><b>${calc.credited} pts</b></div><div><small>Rule limit</small><b>${calc.cap} pts</b></div></div><div class="awardtotal"><span>${calc.available?'Available for this submission':'Rule limit reached'}</span><strong>${calc.available} points</strong></div></div><small>¹ Segment ${E(calc.head)}: ${calc.credited}/${calc.cap}. Group ${gr[calc.group]}: ${calc.groupTotal}/40. Verify older unclassified records and any earlier award for this event. Do not combine participation with winning or count the same achievement twice.</small><label class="confirm"><input type="checkbox" id="confirmed" ${proofOpened.has(r.id)?'':'disabled'} onchange="$('#accept').disabled=!this.checked">I have reviewed the submitted proof, confirmed the rule and checked prior awards.</label>`}
function ruleLabel(x){return ruleRef(x)+' — '+x[1]}
function rulePicker(id,key=''){let x=rules.find(v=>v[0]===key&&(id!=='teacherRule'||awardCatalog[v[0]]));return `<div class="rulepicker"><input type="hidden" id="${id}" value="${x?x[0]:''}"><div class="field">${I('search')}<input type="text" id="${id}Search" aria-label="Search by handbook rule number or activity name" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}List" autocomplete="off" placeholder="Type a rule number or activity, e.g. 1.8 or blood" value="${x?E(ruleLabel(x)):''}" onfocus="ruleResults('${id}')" oninput="ruleTyping('${id}')" onkeydown="ruleKeys(event,'${id}')" onblur="hideRules('${id}')"></div><div class="rulehits" role="listbox" aria-label="Matching handbook entries" id="${id}List" hidden></div></div>`}
function hideRules(id){let el=$('#'+id+'Search');el.setAttribute('aria-expanded','false');el.removeAttribute('aria-activedescendant');$('#'+id+'List').hidden=true}
function ruleTyping(id){$('#'+id).value='';if(id==='teacherRule')refreshAward();else{$('#suggestion').innerHTML=''}ruleResults(id)}
function ruleResults(id){let input=$('#'+id+'Search'),box=$('#'+id+'List'),terms=($('#'+id).value?'':input.value).trim().toLowerCase().replace(/^rule\s*/,'').split(/\s+/).filter(Boolean),found=rules.filter(x=>(id!=='teacherRule'||awardCatalog[x[0]])&&terms.every(t=>(x[0]+' '+ruleRef(x)+' '+x[1]+' '+x[4]+(x[0]==='1.11'?' 1.1.11':'')).toLowerCase().replace(/[-–]/g,' ').includes(t.replace(/[-–]/g,' '))));input.dataset.index='-1';input.removeAttribute('aria-activedescendant');box.innerHTML=found.length?found.map((x,i)=>`<div role="option" id="${id}Opt${i}" aria-selected="false" data-key="${x[0]}" onmousedown="event.preventDefault()" onclick="pickRule('${id}','${x[0]}')"><b>${ruleRef(x)}</b><span>${E(x[1])}</span><small>Group ${gr[x[2]]}</small></div>`).join(''):'<p>No matching handbook entry. Try a shorter name or check the handbook.</p>';box.hidden=false;input.setAttribute('aria-expanded','true')}
function pickRule(id,key){let x=rules.find(v=>v[0]===key);$('#'+id).value=key;$('#'+id+'Search').value=ruleLabel(x);hideRules(id);if(id==='teacherRule')refreshAward();else suggest()}
function ruleKeys(e,id){let input=e.target,box=$('#'+id+'List');if(e.key==='Escape'){e.preventDefault();hideRules(id);return}if(!['ArrowDown','ArrowUp','Enter'].includes(e.key))return;e.preventDefault();if(box.hidden)ruleResults(id);let opts=[...box.querySelectorAll('[role=option]')];if(!opts.length)return;let i=+input.dataset.index;if(e.key==='Enter'){if(i>=0||opts.length===1)pickRule(id,opts[Math.max(0,i)].dataset.key);return}i=e.key==='ArrowDown'?(i+1)%opts.length:(i<=0?opts.length-1:i-1);input.dataset.index=i;opts.forEach((o,j)=>o.setAttribute('aria-selected',j===i));input.setAttribute('aria-activedescendant',opts[i].id);opts[i].scrollIntoView({block:'nearest'})}
